using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Windows.Forms;
namespace V15Voice {public partial class MainForm {
 string lastVoiceReport="";
 VoiceReportContext ReportContext(string source,IEnumerable<Cue> input,BatchJob job=null){
  var p=catalog.Get(Key());return new VoiceReportContext{SourcePath=source??"",SourceCues=VoiceRenderReport.Snapshot(input),VoiceKey=p.Key,Description=p.Description,Styles=p.Styles,VoiceSource=p.Source,UserNote=catalog.Note(p.Key),Written=r=>{lastVoiceReport=r.PathName;if(job!=null)job.ReportPath=r.PathName;}};
 }
 RenderOptions ReportSettings(){return new RenderOptions{Prose=proseInput,Anchored=AnchoredMode,Locked=!proseInput&&mode.SelectedIndex==0,BaseSpeed=(double)speed.Value,MinSpeed=(double)minSpeed.Value,MaxSpeed=(double)maxSpeed.Value,GentleFit=fitMode.SelectedIndex==0,Gap=(double)gap.Value,SlowShort=slow.Checked,JoinSentences=joinSentences.Checked,Punctuation=(PunctuationMode)punctuationMode.SelectedIndex,CommaPause=(double)commaPause.Value,StopPause=(double)stopPause.Value,QuestionPause=(double)questionPause.Value,ParagraphPause=(double)paragraphPause.Value,Breathing=(BreathMode)breathMode.SelectedIndex,BreathLevel=(double)breathVolume.Value/100,BreathEvery=(int)breathEvery.Value,NormalizeLoudness=normalizeLoudness.Checked,TargetLufs=(double)targetLufs.Value};}
 VoiceRenderReport FailureReport(string source,List<Cue> input,Exception error,BatchJob job=null){
  try{var o=ReportSettings();if(job!=null){o.Prose=!job.Timed;AnchoredVoice.ConfigureBatch(o,job.Timed,batchMode.SelectedIndex,mode.SelectedIndex);}o.ReportContext=ReportContext(source,input,job);o.ReportContext.Purpose="Lỗi kiểm tra/nhập file trước khi tạo WAV · snapshot cuối đã xác nhận trong app";KokoroEngine e=active;bool own=e==null;if(own)e=EngineFor(catalog.Get(Key()));try{var r=new VoiceRenderReport(input,e,o,String.IsNullOrEmpty(source)?Path.Combine(stateDir,"kich_ban.wav"):OutputFiles.Beside(source));r.Step("INPUT","Nhập file / kiểm tra thiết lập trước render");r.Finish(error is OperationCanceledException?"ĐÃ DỪNG":"THẤT BẠI","",error);return r;}finally{if(own)e.Dispose();}}catch(Exception reportError){status.Text="Chưa lưu được báo cáo lỗi: "+reportError.Message;return null;}
 }
 void OpenVoiceReport(bool queued){try{string path=queued&&jobGrid.CurrentRow!=null?jobs[jobGrid.CurrentRow.Index].ReportPath:lastVoiceReport;if(String.IsNullOrEmpty(path)||!File.Exists(path)){status.Text="Chưa có báo cáo cho lần chạy/file đang chọn.";return;}Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception e){Error(e);}}
 string ReportMessage(VoiceRenderReport report){return report==null?"":(!String.IsNullOrEmpty(report.PathName)?"\r\nBáo cáo: "+report.PathName:"")+(report.SaveWarning.Length>0?"\r\n"+report.SaveWarning:"");}
}}
